import os
import json
import queue
import threading
from typing import Any, Callable, Dict, Iterable, Iterator, List, Optional

import azure.cognitiveservices.speech as speechsdk


def _event_to_dict(evt: Any, final: bool) -> Dict[str, Any]:
    result = getattr(evt, "result", None)
    text = getattr(result, "text", "") if result is not None else ""
    reason = getattr(result, "reason", None) if result is not None else None

    offset = getattr(result, "offset", None) if result is not None else None
    duration = getattr(result, "duration", None) if result is not None else None

    alternatives: List[Dict[str, Any]] = []
    if result is not None:
        for idx in range(getattr(result, "number_of_alternatives", 0) or 0):
            alt = result.alternatives[idx]
            alternatives.append(
                {
                    "transcript": getattr(alt, "transcript", ""),
                    "confidence": getattr(alt, "confidence", None),
                }
            )

    return {
        "type": "final" if final else "partial",
        "text": text,
        "reason": str(reason) if reason is not None else None,
        "offset": offset,
        "duration": duration,
        "alternatives": alternatives,
    }


class AzureStreamingRecognizer:
    def __init__(
        self,
        subscription_key: Optional[str] = None,
        region: Optional[str] = None,
        language: str = "en-US",
    ) -> None:
        self.subscription_key = subscription_key or os.getenv("AZURE_SPEECH_KEY")
        self.region = region or os.getenv("AZURE_SPEECH_REGION")
        self.language = language

        if not self.subscription_key or not self.region:
            raise ValueError(
                "Azure Speech credentials are required via AZURE_SPEECH_KEY and AZURE_SPEECH_REGION."
            )

    def recognize_stream(
        self,
        audio_chunks: Iterable[bytes],
        sample_rate: int = 16000,
        on_partial: Optional[Callable[[Dict[str, Any]], None]] = None,
        on_final: Optional[Callable[[Dict[str, Any]], None]] = None,
    ) -> List[Dict[str, Any]]:
        speech_config = speechsdk.SpeechConfig(
            subscription=self.subscription_key,
            region=self.region,
        )
        speech_config.speech_recognition_language = self.language
        speech_config.output_format = speechsdk.OutputFormat.Detailed

        stream_format = speechsdk.audio.AudioStreamFormat(
            samples_per_second=sample_rate,
            bits_per_sample=16,
            channels=1,
        )
        push_stream = speechsdk.audio.PushAudioInputStream(stream_format)
        audio_config = speechsdk.audio.AudioConfig(stream=push_stream)
        recognizer = speechsdk.SpeechRecognizer(
            speech_config=speech_config,
            audio_config=audio_config,
        )

        events: List[Dict[str, Any]] = []
        done = threading.Event()
        lock = threading.Lock()

        def _emit(evt_dict: Dict[str, Any], cb: Optional[Callable[[Dict[str, Any]], None]]) -> None:
            with lock:
                events.append(evt_dict)
            if cb:
                cb(evt_dict)

        def recognized_handler(evt: Any) -> None:
            if evt.result.reason == speechsdk.ResultReason.RecognizedSpeech:
                _emit(_event_to_dict(evt, final=True), on_final)

        def recognizing_handler(evt: Any) -> None:
            if evt.result.reason == speechsdk.ResultReason.RecognizingSpeech:
                _emit(_event_to_dict(evt, final=False), on_partial)

        def canceled_handler(_: Any) -> None:
            done.set()

        def session_stopped_handler(_: Any) -> None:
            done.set()

        recognizer.recognizing.connect(recognizing_handler)
        recognizer.recognized.connect(recognized_handler)
        recognizer.canceled.connect(canceled_handler)
        recognizer.session_stopped.connect(session_stopped_handler)

        recognizer.start_continuous_recognition()

        try:
            for chunk in audio_chunks:
                if chunk:
                    push_stream.write(chunk)
        finally:
            push_stream.close()
            done.wait(timeout=30)
            recognizer.stop_continuous_recognition()

        return events


def recognize_streaming_events(
    audio_chunks: Iterable[bytes],
    sample_rate: int = 16000,
    language: str = "en-US",
    subscription_key: Optional[str] = None,
    region: Optional[str] = None,
) -> Iterator[Dict[str, Any]]:
    recognizer = AzureStreamingRecognizer(
        subscription_key=subscription_key,
        region=region,
        language=language,
    )

    q: "queue.Queue[Optional[Dict[str, Any]]]" = queue.Queue()

    def on_partial(evt: Dict[str, Any]) -> None:
        q.put(evt)

    def on_final(evt: Dict[str, Any]) -> None:
        q.put(evt)

    def worker() -> None:
        try:
            recognizer.recognize_stream(
                audio_chunks=audio_chunks,
                sample_rate=sample_rate,
                on_partial=on_partial,
                on_final=on_final,
            )
        finally:
            q.put(None)

    t = threading.Thread(target=worker, daemon=True)
    t.start()

    while True:
        item = q.get()
        if item is None:
            break
        yield item


if __name__ == "__main__":
    import sys

    def _read_audio(path: Optional[str]) -> Iterable[bytes]:
        if path:
            with open(path, "rb") as f:
                while True:
                    data = f.read(4096)
                    if not data:
                        break
                    yield data
        else:
            while True:
                data = sys.stdin.buffer.read(4096)
                if not data:
                    break
                yield data

    audio_path = sys.argv[1] if len(sys.argv) > 1 else None
    for event in recognize_streaming_events(_read_audio(audio_path)):
        print(json.dumps(event, ensure_ascii=False))
